p=ggplot(s,aes(state,MP10,color=state))+geom_point(position=position_jitter(width=.09,height=0,seed=cfg$seed),size=2)+geom_line(data=m,aes(y=MP10_mean,group=cell_line),color='grey45',linewidth=.5)+geom_point(data=m,aes(y=MP10_mean),shape=18,size=3.5)+facet_wrap(~cell_line,nrow=1)+scale_color_manual(values=cols[levels(s$state)])+jin_theme()+theme(axis.text.x=element_text(angle=45,hjust=1),legend.position='none')+labs(x=NULL,y='MP10 ssGSEA score');export(p,'B_cell_line_RNA_replicates',13,4.7,'02_cell_lines/sample_scores.tsv;line_state_scores.tsv','3 passage RNA samples per state; diamonds are means; 5 biological backgrounds')
