for(co in c('GSE169455','GSE212810'))for(ep in c('nonresponse','non_pCR')){
 d=a[cohort==co];d=d[if(co=='GSE169455')fallback_inclusion else strict_inclusion];scp=if(co=='GSE169455')'NAC_regimen_unverified_sensitivity'else 'strict_cisplatin_NAC'
 # data.table uses explicit local lookup to avoid same-name scope ambiguity.
 pv=rr[cohort==co&scope==scp&endpoint==ep&adjustment=='none',P][1]
 d[,group:=fifelse(is.na(get(ep)),'Unknown',fifelse(get(ep)==0,'Response','Nonresponse'))];lab=if(co=='GSE169455')'GSE169455 (NAC; regimen unverified)'else 'GSE212810 (strict cisplatin NAC)';lab=paste0(lab,'\n',if(ep=='nonresponse')'Good pathology: <=ypT1N0'else 'Strict pCR: ypT0N0')
 p=plot_grouped_boxplot(d,'group','MP10_z',lab,pv,'MP10 ssGSEA (fixed cohort z)',order=c('Response','Nonresponse','Unknown'),colors=cols[c('Response','Nonresponse','Unknown')],xlab='Pathological response',seed=cfg$seed,p_label='p');export(p,paste0('C_',co,'_',ep),6.4,5.3,'03_clinical/patient_inclusion_endpoint_audit.tsv;model_results.tsv',paste(scp,ep,'P from unadjusted logistic model; unknown excluded from model'))
}
for(ep in c('nonresponse','non_pCR')){
 d=rr[endpoint==ep];d[,model:=fcase(adjustment=='none','Unadjusted',adjustment=='cT','Adjusted cT',default='Adjusted subtype')];d[,shortscope:=fcase(scope=='strict_cisplatin_NAC','strict cisplatin',scope=='NAC_regimen_unverified_sensitivity','NAC regimen unknown',scope=='all_NAC_including_GCb_sensitivity','all NAC (incl. GCb)',scope=='strict_cisplatin_cycles_ge3_sensitivity','cisplatin >=3 cycles',default='induction')];d[,label:=paste(cohort,shortscope,model,paste0('(n=',n,')'),sep=' | ')];d[,label:=factor(label,levels=rev(unique(label)))];d[,methodmark:=ifelse(method=='Firth_Jeffreys_profile_likelihood','Firth','GLM')]
 p=ggplot(d,aes(OR,label,color=model))+geom_vline(xintercept=1,linetype=2,linewidth=.4,color='grey45')+geom_errorbar(aes(xmin=CI_low,xmax=CI_high),orientation='y',width=.16,linewidth=.5,na.rm=TRUE)+geom_point(aes(shape=methodmark),size=2.6,na.rm=TRUE)+geom_text(data=d[!is.finite(OR)],inherit.aes=FALSE,mapping=aes(x=1,y=label,label='BLOCKED: regimen missing'),size=3.5)+scale_x_log10()+scale_color_manual(values=c(Unadjusted='#d45087','Adjusted cT'='#377eb8','Adjusted subtype'='#984ea3'))+scale_shape_manual(values=c(Firth=17,GLM=16),guide='none')+jin_theme()+labs(x='Odds ratio per 1 SD higher MP10 (95% CI)',y=NULL,color='Model');export(p,paste0('D_clinical_OR_',ep),14,7,'03_clinical/model_results.tsv',paste(ep,'; triangles use Firth profile likelihood; all other points GLM Wald'))
}
